const small=load("priorread2").results;
const prior={version:small.find(x=>x.pointer==="/version").value,
full_target:small.find(x=>x.pointer==="/full_target").value,
proof:load("repairread0").value,
lean_header:small.find(x=>x.pointer==="/lean_header").value,
dependencies:load("repairread1").value,
replacements:small.find(x=>x.pointer==="/replacements").value};
store("frozen_prior",JSON.parse(JSON.stringify(prior)));
const b2=prior.dependencies.find(x=>x.id==="B002");
b2.statement=`For every n∈ℕ, F,F' : ℝ → (Fin n → ℝ) → ℝ, b : (Fin n → ℝ) → ℝ, t₀∈ℝ and s⊆ℝ, assume:
(1) s is a neighborhood of t₀;
(2) eventually as t→t₀, F(t,·) is Lebesgue-ae strongly measurable;
(3) F(t₀,·) is Lebesgue integrable;
(4) F'(t₀,·) is Lebesgue-ae strongly measurable;
(5) for Lebesgue-almost every spatial x, for every t∈s, |F'(t,x)|≤b(x), that is, ∀ᵐ x ∂volume, ∀ t∈s, |F'(t,x)|≤b(x);
(6) b is Lebesgue integrable;
(7) for Lebesgue-almost every spatial x, for every t∈s, HasDerivAt (r↦F(r,x)) (F'(t,x)) t holds, that is, ∀ᵐ x ∂volume, ∀ t∈s, HasDerivAt (r↦F(r,x)) (F'(t,x)) t.
Then F'(t₀,·) is Lebesgue integrable and HasDerivAt (t↦∫ F(t,x) dx) (∫ F'(t₀,x) dx) t₀. In (5) and (7), the almost-everywhere spatial quantifier precedes the universal time quantifier. Each spatial exceptional set is independent of t; intersecting the two full-measure spatial sets gives one on which both hypotheses hold for every t∈s.`;
b2.justification=`Exact native theorem hasDerivAt_integral_of_dominated_loc_of_deriv_le, Mathlib/Analysis/Calculus/ParametricIntegral.lean:284–306, specialized to real parameters and scalar Lebesgue integrals. Its h_bound and h_diff both have the order ∀ᵐ x ∂volume, ∀ t∈s. The registered statement now spells out precisely that order, including a time-independent exceptional set for each hypothesis. The Lean type and proof already had this order and remain unchanged. No interchange of an almost-everywhere spatial quantifier with the time quantifier is used or asserted. In B012 both predicates hold for every spatial x simultaneously for all t∈s_t, so each ae-first hypothesis follows directly from an everywhere statement. The original target, neighborhood, measure and two-part conclusion are preserved.`;
prior.dependencies.find(x=>x.id==="B012").justification=`Use the C from B011, η=t₀/4 and compact C×[t₀−η,t₀+η]. B008 bounds |d| there; max(B₀,0)1_C is an integrable bound by B009 and d=0 off C. For every spatial x, for every r∈s_t=(t₀−η,t₀+η), the bound |d(x,r)|≤b(x) holds. Separately, for every spatial x, for every r∈s_t, B010 gives HasDerivAt (s↦e(x,s)) d(x,r) r. Applying ae_of_all to each complete universal-in-r predicate supplies B002's exact ae-first hypotheses ∀ᵐ x, ∀ r∈s_t; neither step chooses exceptional sets depending on r. Continuity and B011 check the remaining eventual measurability, basepoint measurability and integrability premises in proof paragraph 4.`;
const oldBound="Thus the bound holds for every x and r∈s_t, in particular for ae x.";
const newBound="Thus for every spatial x, for every r∈s_t, the bound holds. In particular, the entire predicate (∀ r∈s_t, |d(x,r)|≤b(x)) holds for Lebesgue-almost every x. This is exactly the ae-first order required by B002; the exceptional set can be empty.";
if(!prior.proof.includes(oldBound))throw Error("missing bound patch anchor");
prior.proof=prior.proof.replace(oldBound,newBound);
const oldApply="the derivative bound holds everywhere by the preceding cases; b is integrable by B009; and the pointwise HasDerivAt assertions for every r∈s_t follow from paragraph 2 because r>0. B002 concludes";
const newApply="the bound hypothesis is ∀ᵐ x ∂volume, ∀ r∈s_t, |d(x,r)|≤b(x), obtained by applying ae_of_all volume to the universal-in-r predicate established in the preceding cases; b is integrable by B009; and for every spatial x, for every r∈s_t, paragraph 2 gives HasDerivAt (s↦e(x,s)) d(x,r) r because r>0. A second application of ae_of_all volume to this universal-in-r derivative predicate supplies ∀ᵐ x ∂volume, ∀ r∈s_t, HasDerivAt (s↦e(x,s)) d(x,r) r. These are the exact quantifier orders in B002's native theorem and prepared Lean proposition. Both hold everywhere in x, with no time-dependent spatial exceptional sets. B002 concludes";
if(!prior.proof.includes(oldApply))throw Error("missing application patch anchor");
prior.proof=prior.proof.replace(oldApply,newApply);
prior.proof+=`\n\nLocated repair response (repair-findings.json, B002): the former B002 prose could be read as placing the universal time quantifier before the almost-everywhere spatial quantifier. That weaker hypothesis does not imply the native theorem's conclusion. The revised B002 statement places the ae spatial quantifier first in each of the bound and derivative hypotheses, matching its unchanged closed Lean type and the actual native source at lines 291–292. B002's justification and paragraph 4/B012 now explicitly verify this order by deriving each ae hypothesis from ∀ x, ∀ r∈s_t. Thus the use requires no quantifier exchange. This repair changes no original H, target, object definition, parameter range, measure, normalization or dependency edge.`;
const repl=prior.replacements.find(x=>x.original_dependency==="Differentiation under the integral by mean value theorem and dominated convergence");
repl.explanation="Apply the native dominated derivative theorem with the ae spatial quantifier preceding the universal time quantifier in both derivative and bound hypotheses. B012 supplies each by an everywhere-in-space, universal-in-time statement derived from the original locally uniform slab support.";
store("repaired_artifact",prior);
text({changedFields:["/dependencies/1/statement","/dependencies/1/justification","/dependencies/11/justification","/proof","/replacements/3/explanation"],nativeTypesUnchanged:prior.dependencies.filter(d=>d.lean).every(d=>JSON.stringify(d.lean)===JSON.stringify(load("frozen_prior").dependencies.find(x=>x.id===d.id).lean)),fullTargetUnchanged:prior.full_target===load("frozen_prior").full_target});
text(await tools.save_basis_draft({artifact:prior}));
text(await tools.check_draft({artifact:prior}));

